CREATE OR REPLACE FUNCTION public.save_crm_customer(p_customer jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; lid uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Owner access required'; END IF; IF length(trim(coalesce(p_customer->>'name','')))<2 OR length(p_customer->>'name')>100 OR length(coalesce(p_customer->>'phone',''))>30 OR length(coalesce(p_customer->>'email',''))>255 OR length(coalesce(p_customer->>'billing_address',''))>250 OR length(coalesce(p_customer->>'notes',''))>4000 OR coalesce(p_customer->>'customer_type','') NOT IN ('residential','commercial','property_manager') THEN RAISE EXCEPTION 'Invalid customer'; END IF; IF p_customer->>'id' IS NULL THEN INSERT INTO public.leads(name,phone,email,source,page) VALUES(trim(p_customer->>'name'),coalesce(p_customer->>'phone',''),nullif(p_customer->>'email',''),'contact','owner-crm') RETURNING id INTO cid; ELSE cid:=(p_customer->>'id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.crm_customers WHERE id=cid) THEN RAISE EXCEPTION 'Customer unavailable'; END IF; END IF; UPDATE public.crm_customers SET name=trim(p_customer->>'name'),phone=coalesce(p_customer->>'phone',''),email=coalesce(p_customer->>'email',''),billing_address=coalesce(p_customer->>'billing_address',''),customer_type=p_customer->>'customer_type',notes=coalesce(p_customer->>'notes','') WHERE id=cid RETURNING source_lead_id INTO lid; IF lid IS NOT NULL THEN UPDATE public.leads SET name=trim(p_customer->>'name'),phone=coalesce(p_customer->>'phone',''),email=nullif(p_customer->>'email','') WHERE id=lid; END IF; RETURN cid; END; $$;